<?php
require_once __DIR__.'/../includes/functions.php';require_login();$rows=$pdo->query('SELECT t.*,u.nama AS petugas,p.nama_pelanggan FROM transaksi t JOIN users u ON u.id=t.user_id LEFT JOIN pelanggan p ON p.id=t.pelanggan_id ORDER BY t.tanggal DESC')->fetchAll();$total=$pdo->query('SELECT COALESCE(SUM(total),0) FROM transaksi')->fetchColumn();$page_title='Laporan';require __DIR__.'/../includes/header.php';
?><div class="card"><h2>Laporan Penjualan</h2><p>Total seluruh penjualan: <b>Rp <?=number_format($total,0,',','.')?></b></p><div class="table-wrap"><table><tr><th>No</th><th>Tanggal</th><th>Petugas</th><th>Pelanggan</th><th>Total</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['tanggal'])?></td><td><?=e($r['petugas'])?></td><td><?=e($r['nama_pelanggan']??'Umum')?></td><td>Rp <?=number_format($r['total'],0,',','.')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Belum ada transaksi.</td></tr><?php endif;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
